QUESTIONS = [{'question': 'Which blood pressure reading is classified as Stage 2 hypertension under AHA guidelines?', 'options': ['A. 110/70 mmHg', 'B. 118/76 mmHg', 'C. 145/95 mmHg', 'D. 125/78 mmHg'], 'answer': 'C', 'explanation': 'Stage 2 hypertension begins at systolic 140 or diastolic 90 mmHg.'}, {'question': 'A patient has an oxygen saturation of 86% at sea level. What is the most appropriate response?', 'options': ['A. Ignore the reading', 'B. Seek immediate medical evaluation', 'C. Wait until the next annual checkup', 'D. Begin strenuous exercise'], 'answer': 'B', 'explanation': 'An SpO2 of 86% is dangerously low for most people and requires urgent assessment.'}, {'question': 'Which organ primarily produces insulin?', 'options': ['A. Liver', 'B. Kidneys', 'C. Pancreas', 'D. Thyroid'], 'answer': 'C', 'explanation': 'The pancreas produces insulin to help regulate blood glucose.'}, {'question': 'A patient suddenly develops facial drooping, arm weakness, and slurred speech. What should happen first?', 'options': ['A. Schedule a routine appointment', 'B. Encourage the patient to sleep', 'C. Give the patient food', 'D. Call emergency services immediately'], 'answer': 'D', 'explanation': 'These are possible stroke symptoms requiring emergency medical response.'}, {'question': 'Which measurement is most directly used to evaluate long-term blood glucose control?', 'options': ['A. Hemoglobin A1c', 'B. Blood pressure', 'C. Oxygen saturation', 'D. Body temperature'], 'answer': 'A', 'explanation': 'HbA1c reflects average blood glucose over approximately 2-3 months.'}, {'question': 'What is the typical resting heart rate range for most healthy adults?', 'options': ['A. 20-40 beats/min', 'B. 60-100 beats/min', 'C. 110-150 beats/min', 'D. 150-200 beats/min'], 'answer': 'B', 'explanation': 'A typical adult resting heart rate is 60-100 beats per minute, although athletes may have lower rates.'}, {'question': 'Which condition is commonly associated with reduced insulin sensitivity?', 'options': ['A. Type 2 diabetes', 'B. Asthma', 'C. Appendicitis', 'D. Pneumonia'], 'answer': 'A', 'explanation': 'Insulin resistance is a major characteristic of Type 2 diabetes.'}, {'question': 'Which vital sign directly measures the percentage of hemoglobin saturated with oxygen?', 'options': ['A. Heart rate', 'B. Blood pressure', 'C. SpO2', 'D. Respiratory rate'], 'answer': 'C', 'explanation': 'SpO2 estimates peripheral oxygen saturation using pulse oximetry.'}, {'question': 'Which healthcare AI application is an example of supervised machine learning?', 'options': ['A. Displaying static hospital information', 'B. Predicting disease risk from labeled patient records', 'C. Printing a medical document', 'D. Opening an appointment calendar'], 'answer': 'B', 'explanation': 'Supervised learning uses labeled examples to train predictive models.'}, {'question': 'An AI model identifies a patient as low-risk, but the patient actually has a serious condition. What type of error occurred?', 'options': ['A. True positive', 'B. True negative', 'C. False positive', 'D. False negative'], 'answer': 'D', 'explanation': 'A false negative occurs when a model misses an actual positive condition.'}]
